int n = prices.length;
int[][] dp = new int[n][3];

dp[0][0] = 0;              // ready, no profit
dp[0][1] = -prices[0];    // bought on day 0
dp[0][2] = 0;              // can't be in cooldown on day 0

for (int i = 1; i < n; i++) {
    dp[i][0] = Math.max(dp[i-1][0], dp[i-1][2]);
    dp[i][1] = Math.max(dp[i-1][1], dp[i-1][0] - prices[i]);
    dp[i][2] = dp[i-1][1] + prices[i];
}

return Math.max(dp[n-1][0], dp[n-1][2]);

int[] prev = new int[3];
int[] curr = new int[3];

prev[0] = 0;
prev[1] = -prices[0];
prev[2] = 0;

for (int i = 1; i < n; i++) {
    curr[0] = Math.max(prev[0], prev[2]);
    curr[1] = Math.max(prev[1], prev[0] - prices[i]);
    curr[2] = prev[1] + prices[i];
    prev = curr.clone();
}

return Math.max(prev[0], prev[2]);
